1	// src/lib/energy.js
2	//
3	// Live-Daten zum deutschen Strommarkt – nur öffentliche, schlüsselfreie Quellen:
4	//   - Fraunhofer ISE Energy-Charts (CC BY 4.0): Day-Ahead-Preis DE-LU in
5	//     15-Minuten-Auflösung und öffentliche Nettostromerzeugung je Quelle.
6	//     https://api.energy-charts.info
7	//   - aWATTar (Fallback für die Preise): stündlicher Day-Ahead-Preis.
8	//
9	// Alle Abrufe laufen serverseitig mit Next-Cache (revalidate), damit Besucher
10	// nie direkt die Drittanbieter treffen und die Seite schnell bleibt.
11	
12	const EC = "https://api.energy-charts.info";
13	
14	// Umsatzsteuer & typische Netzentgelte/Umlagen – für die Einordnung
15	// "was kostet eine kWh mit dynamischem Tarif ungefähr". Bewusst als
16	// Orientierung gekennzeichnet.
17	export const TARIF_ANNAHMEN = {
18	  aufschlagCt: 19.5, // Netzentgelt, Abgaben, Umlagen, Marge (netto, ct/kWh) – grobe Orientierung 2026
19	  mwst: 0.19,
20	  festpreisCt: 36, // durchschnittlicher Haushalts-Festpreis in ct/kWh brutto (Orientierung)
21	};
22	
23	// Abrufschutz (Masterplan S0 Nr. 8): Ein hängender Drittanbieter darf Render-/ISR-Worker von
24	// Startseite, /energie-live und /api/energie/live nicht blockieren. Je Versuch höchstens
25	// TIMEOUT_MS, insgesamt VERSUCHE Versuche mit wachsender Pause; 4xx wird nicht wiederholt.
26	// Schlimmster Fall je Quelle: 2 × 6 s + 0,4 s ≈ 12,4 s, danach greift der Fallback des Aufrufers.
27	const TIMEOUT_MS = 6000;
28	const VERSUCHE = 2;
29	const PAUSE_MS = 400;
30	
31	const warte = (ms) => new Promise((r) => setTimeout(r, ms));
32	
33	async function holeJson(url, revalidate) {
34	  let letzterFehler;
35	  for (let versuch = 1; versuch <= VERSUCHE; versuch++) {
36	    try {
37	      const res = await fetch(url, {
38	        next: { revalidate },
39	        signal: AbortSignal.timeout(TIMEOUT_MS),
40	        headers: { Accept: "application/json", "User-Agent": "oekoinvest energy widget" },
41	      });
42	      if (res.ok) return await res.json();
43	      letzterFehler = new Error(`${url} -> ${res.status}`);
44	      // Client-Fehler (außer 408/429) ändern sich durch Wiederholen nicht
45	      if (res.status < 500 && res.status !== 408 && res.status !== 429) break;
46	    } catch (e) {
47	      letzterFehler = e?.name === "TimeoutError" ? new Error(`${url} -> Timeout nach ${TIMEOUT_MS} ms`) : e;
48	    }
49	    if (versuch < VERSUCHE) await warte(PAUSE_MS * versuch);
50	  }
51	  throw letzterFehler;
52	}
53	
54	/** Tagesbeginn (lokal Europe/Berlin) als ISO-Datum YYYY-MM-DD */
55	function berlinDatum(offsetTage = 0) {
56	  const d = new Date(Date.now() + offsetTage * 86400000);
57	  return new Intl.DateTimeFormat("sv-SE", { timeZone: "Europe/Berlin" }).format(d);
58	}
59	
60	/**
61	 * Day-Ahead-Preise für heute (und morgen, falls schon veröffentlicht – ab ca. 13 Uhr).
62	 * Rückgabe: [{ t: ms, eurMwh }]
63	 */
64	export async function getSpotPrices() {
65	  try {
66	    const start = berlinDatum(0);
67	    const ende = berlinDatum(2);
68	    const j = await holeJson(`${EC}/price?bzn=DE-LU&start=${start}&end=${ende}`, 900);
69	    const punkte = (j.unix_seconds || [])
70	      .map((s, i) => ({ t: s * 1000, eurMwh: j.price?.[i] }))
71	      .filter((p) => typeof p.eurMwh === "number");
72	    if (punkte.length) return { quelle: "Energy-Charts (Fraunhofer ISE)", aufloesungMin: 15, punkte };
73	  } catch (e) {
74	    console.error("energy-charts price:", e.message);
75	  }
76	  try {
77	    const j = await holeJson("https://api.awattar.de/v1/marketdata", 900);
78	    const punkte = (j.data || []).map((p) => ({ t: p.start_timestamp, eurMwh: p.marketprice }));
79	    return { quelle: "aWATTar", aufloesungMin: 60, punkte };
80	  } catch (e) {
81	    console.error("awattar:", e.message);
82	    return { quelle: null, aufloesungMin: 60, punkte: [] };
83	  }
84	}
85	
86	/**
87	 * Stromerzeugung nach Quelle (Energy-Charts public_power) ab gestern 0 Uhr bis jetzt.
88	 * Gestern ist mit dabei, damit Diagramme auch kurz nach Mitternacht einen
89	 * vollständigen 24-Stunden-Verlauf zeigen können. Die Kennzahlen im Snapshot
90	 * nutzen weiterhin den jüngsten Wert (idx).
91	 */
92	export async function getGeneration() {
93	  try {
94	    const j = await holeJson(`${EC}/public_power?country=de&start=${berlinDatum(-1)}&end=${berlinDatum(1)}`, 900);
95	    const zeiten = (j.unix_seconds || []).map((s) => s * 1000);
96	    const reihe = (name) => j.production_types?.find((p) => p.name === name)?.data || [];
97	    const summe = (...namen) =>
98	      zeiten.map((_, i) => namen.reduce((acc, n) => acc + (Number(reihe(n)[i]) || 0), 0));
99	
100	    const serien = {
101	      solar: reihe("Solar"),
102	      windOnshore: reihe("Wind onshore"),
103	      windOffshore: reihe("Wind offshore"),
104	      biomasse: reihe("Biomass"),
105	      wasser: summe("Hydro Run-of-River", "Hydro water reservoir"),
106	      braunkohle: reihe("Fossil brown coal / lignite"),
107	      steinkohle: reihe("Fossil hard coal"),
108	      gas: reihe("Fossil gas"),
109	      // Rest der öffentlichen Nettoerzeugung (Müll, Öl, Grubengas, Geothermie, Pumpspeicher, Sonstige)
110	      sonstige: summe("Waste", "Fossil oil", "Fossil coal-derived gas", "Geothermal", "Others", "Hydro pumped storage"),
111	      last: reihe("Load"),
112	      eeAnteil: reihe("Renewable share of load"),
113	    };
114	
115	    // Letzter Zeitpunkt mit Solar- UND Lastwert
116	    let idx = -1;
117	    for (let i = zeiten.length - 1; i >= 0; i--) {
118	      if (serien.solar[i] != null && serien.last[i] != null) { idx = i; break; }
119	    }
120	    return { quelle: "Energy-Charts (Fraunhofer ISE)", zeiten, serien, idx };
121	  } catch (e) {
122	    console.error("energy-charts power:", e.message);
123	    return { quelle: null, zeiten: [], serien: {}, idx: -1 };
124	  }
125	}
126	
127	/** Kompakte Live-Zusammenfassung für Ticker, Widgets und Dashboard. */
128	export async function getEnergySnapshot() {
129	  const [preise, erzeugung] = await Promise.all([getSpotPrices(), getGeneration()]);
130	  const jetzt = Date.now();
131	  const schritt = preise.aufloesungMin * 60000;
132	
133	  const heuteStr = berlinDatum(0);
134	  const tagVon = (t) => new Intl.DateTimeFormat("sv-SE", { timeZone: "Europe/Berlin" }).format(new Date(t));
135	  const heute = preise.punkte.filter((p) => tagVon(p.t) === heuteStr);
136	  const morgen = preise.punkte.filter((p) => tagVon(p.t) === berlinDatum(1));
137	  const aktuell = preise.punkte.find((p) => p.t <= jetzt && jetzt < p.t + schritt) || null;
138	
139	  const stat = (arr) => {
140	    if (!arr.length) return null;
141	    const werte = arr.map((p) => p.eurMwh);
142	    const min = arr.reduce((a, b) => (b.eurMwh < a.eurMwh ? b : a));
143	    const max = arr.reduce((a, b) => (b.eurMwh > a.eurMwh ? b : a));
144	    return { avg: werte.reduce((a, b) => a + b, 0) / werte.length, min, max, negativ: werte.filter((w) => w < 0).length };
145	  };
146	
147	  const { serien, idx, zeiten } = erzeugung;
148	  const wert = (s) => (idx >= 0 && serien[s] ? Number(serien[s][idx]) || 0 : null);
149	  const wind = idx >= 0 ? (wert("windOnshore") || 0) + (wert("windOffshore") || 0) : null;
150	
151	  return {
152	    stand: new Date().toISOString(),
153	    preis: {
154	      quelle: preise.quelle,
155	      aufloesungMin: preise.aufloesungMin,
156	      aktuell,
157	      heute: stat(heute),
158	      morgen: stat(morgen),
159	      punkte: preise.punkte,
160	    },
161	    erzeugung: {
162	      quelle: erzeugung.quelle,
163	      zeitpunkt: idx >= 0 ? zeiten[idx] : null,
164	      solarMw: wert("solar"),
165	      windMw: wind,
166	      lastMw: wert("last"),
167	      eeAnteil: wert("eeAnteil"),
168	      solarAnteil: idx >= 0 && wert("last") ? (wert("solar") / wert("last")) * 100 : null,
169	      zeiten,
170	      serien,
171	    },
172	  };
173	}
174	
175	/** €/MWh (Börse, netto) -> ct/kWh */
176	export const ctKwh = (eurMwh) => eurMwh / 10;
177	
178	/** Grobe Brutto-Endkundenkosten bei dynamischem Tarif in ct/kWh. */
179	export const dynamischBrutto = (eurMwh) => (ctKwh(eurMwh) + TARIF_ANNAHMEN.aufschlagCt) * (1 + TARIF_ANNAHMEN.mwst);
