1	// src/lib/land/seite.js – Land einer Seite auf dem Server (nutzt react/cache und next/navigation)
2	//
3	// Getrennt von index.js, damit node:test, next.config.mjs, Middleware und Client-Komponenten die
4	// reine Länderlogik ohne Server-Funktionen laden können.
5	//
6	// Jede öffentliche Seite (src/app/(stamm)/…/page.js) ist zugleich ihre Länderfassung: Die Route
7	// src/app/(laender)/[land]/…/page.js exportiert genau diese Seite weiter, Next.js reicht dabei
8	// params.land ("de" | "at" | "ch") durch. Die Seite ruft am Anfang
9	//
10	//   const land = await seitenLand(params);          // "DE" | "AT" | "CH" | null (= gemeinsam)
11	//
12	// und exportiert ihre Metadaten über
13	//
14	//   export const generateMetadata = seitenMetadata("/rechner/pacht", metadata);
15	//
16	// Tiefer liegende Server-Komponenten (z. B. RechnerSeite) lesen das Land danach mit
17	// landDerAnfrage() – ohne es durchreichen zu müssen. Client-Komponenten nutzen useLand()
18	// (src/components/Land/useLand.js), das Land kommt dort aus dem Root-Layout.
19	
20	import { cache } from "react";
21	import { notFound } from "next/navigation";
22	import { landAusPraefix } from "./laender.js";
23	import { alternates, fassungIndexierbar, ogLocale } from "./pfad.js";
24	import { spracheOder } from "../sprache/sprachen.js";
25	import { setzeLandQuelle, uebersetze } from "../sprache/woerterbuch.js";
26	import { schreibweiseFuer, setzeAusgabeLand } from "./schreibweise.js";
27	
28	/** Speicher je Anfrage (React cache): Land und Sprache der gerade gerenderten Seite. */
29	const anfrage = cache(() => ({ land: null, sprache: "de", gesetzt: false }));
30	
31	// Server-Komponenten rufen uebersetze(TEXTE, sprache) ohne Land: Das Land der Anfrage kommt von
32	// hier (Schweizer Schreibweise ohne „ß“ auf /ch und /en/ch, src/lib/land/schreibweise.js).
33	setzeLandQuelle(() => anfrage().land);
34	setzeAusgabeLand(() => anfrage().land); // JSON-LD auf /ch ohne „ß“ (src/components/JsonLd.js)
35	
36	/**
37	 * Sprache aus den Routenparametern: Die englischen Routen (src/app/(en)/en/…, erzeugt mit
38	 * scripts/landfassungen.mjs) reichen params.sprache = "en" an dieselbe Seitenkomponente durch
39	 * (src/lib/sprache/route.js). Ohne Angabe: Deutsch.
40	 */
41	export const spracheAusParams = (p) => spracheOder(p?.sprache);
42	
43	/**
44	 * Land aus den Routenparametern. Ohne params.land: gemeinsame Seite (null).
45	 * Unbekanntes Präfix → 404. Merkt sich das Land für landDerAnfrage().
46	 * @param {Promise<object>|object} params
47	 * @returns {Promise<"DE"|"AT"|"CH"|null>}
48	 */
49	export async function seitenLand(params) {
50	  const p = (await params) || {};
51	  let land = null;
52	  if (p.land !== undefined) {
53	    land = landAusPraefix(p.land);
54	    if (!land) notFound();
55	  }
56	  const a = anfrage();
57	  a.land = land;
58	  a.sprache = spracheAusParams(p);
59	  a.gesetzt = true;
60	  return land;
61	}
62	
63	/**
64	 * Land der aktuellen Seite für Server-Komponenten unterhalb der Seite.
65	 * Nur gültig, nachdem die Seite seitenLand(params) aufgerufen hat (sonst null = gemeinsam).
66	 */
67	export function landDerAnfrage() {
68	  return anfrage().land;
69	}
70	
71	/**
72	 * Sprache der aktuellen Seite ("de" | "en") für Server-Komponenten unterhalb der Seite.
73	 * Nur gültig, nachdem die Seite seitenLand(params) aufgerufen hat (sonst "de").
74	 */
75	export function spracheDerAnfrage() {
76	  return anfrage().sprache;
77	}
78	
79	/**
80	 * generateMetadata für eine öffentliche Seite (gemeinsam, Länderfassung, englische Fassung):
81	 * übernimmt die Basis-Metadaten und setzt canonical, hreflang, og:url und og:locale.
82	 * Noindex bekommen Länderfassungen ohne eigenen Länderinhalt (Register src/lib/land/seiten.js)
83	 * und englische Fassungen, die noch nicht übersetzt sind (src/lib/sprache/seiten.js).
84	 * @param {string | ((p: object) => string)} schluessel Pfad ohne Präfix (bei [slug]-Routen aus params)
85	 * @param {object | ((land: string|null, p: object) => object|Promise<object>)} basis  p.sprache = "de" | "en"
86	 * @param {{ en?: object | ((de: object) => object) }} [woerterbuch] englische Metadaten (title,
87	 *   description, openGraph.title …), tief über die deutschen gelegt (uebersetze()).
88	 */
89	export function seitenMetadata(schluessel, basis, woerterbuch = {}) {
90	  return async function generateMetadata({ params }) {
91	    const p = (await params) || {};
92	    const land = p.land !== undefined ? landAusPraefix(p.land) : null;
93	    const sprache = spracheAusParams(p);
94	    const konkret = typeof schluessel === "function" ? schluessel(p) : schluessel;
95	    const roh = (typeof basis === "function" ? await basis(land, p) : basis) || {};
96	    const b = sprache === "en" && woerterbuch?.en ? uebersetze({ de: roh, en: woerterbuch.en }, "en") : roh;
97	    const a = alternates(konkret, land, { languages: b.alternates?.languages, sprache });
98	    const index = land || sprache !== "de" ? fassungIndexierbar(konkret, land, sprache) : null;
99	    const locale = land || sprache !== "de" ? { locale: ogLocale(land, sprache) } : {};
100	    return schreibweiseFuer({
101	      ...b,
102	      alternates: { ...(b.alternates || {}), ...a, ...(a.languages ? {} : { languages: undefined }) },
103	      ...(b.openGraph ? { openGraph: { ...b.openGraph, url: a.canonical, ...locale } } : {}),
104	      ...(index === false ? { robots: { index: false, follow: true } } : {}),
105	    }, land);
106	  };
107	}
