3	import { useEffect, useState } from "react";
4	
5	// Ein gemeinsamer Abruf pro Seitenaufruf, egal wie viele Widgets ihn nutzen.
6	let zwischenspeicher = null;
7	let laufend = null;
8	
9	export function ladeEnergie(voll = false) {
10	  if (!voll && zwischenspeicher && Date.now() - zwischenspeicher.zeit < 5 * 60000) {
11	    return Promise.resolve(zwischenspeicher.daten);
12	  }
13	  if (!voll && laufend) return laufend;
14	  const p = fetch(`/api/energie/live${voll ? "?voll=1" : ""}`)
15	    .then((r) => (r.ok ? r.json() : null))
16	    .then((d) => {
17	      if (d && !voll) zwischenspeicher = { zeit: Date.now(), daten: d };
18	      return d;
19	    })
20	    .catch(() => null)
21	    .finally(() => {
22	      if (!voll) laufend = null;
23	    });
24	  if (!voll) laufend = p;
25	  return p;
26	}
27	
28	/** Live-Strommarktdaten (Kennzahlen). Aktualisiert alle 5 Minuten. */
29	export default function useEnergyLive({ voll = false, intervall = 5 * 60000 } = {}) {
30	  const [daten, setDaten] = useState(null);
31	
32	  useEffect(() => {
33	    let aktiv = true;
34	    const holen = () => ladeEnergie(voll).then((d) => aktiv && d && setDaten(d));
35	    holen();
36	    const t = setInterval(holen, intervall);
37	    return () => {
38	      aktiv = false;
39	      clearInterval(t);
40	    };
41	  }, [voll, intervall]);
42	
43	  return daten;
44	}
45	
46	// sprache "en" → englisches Zahlenformat (Sprachmodell); ohne Angabe Deutsch wie bisher
47	const LOC = (sprache) => (sprache === "en" ? "en-GB" : "de-DE");
48	
49	export const fmtCt = (eurMwh, stellen = 1, sprache = "de") =>
50	  (eurMwh / 10).toLocaleString(LOC(sprache), { minimumFractionDigits: stellen, maximumFractionDigits: stellen });
51	
52	export const fmtGw = (mw, sprache = "de") =>
53	  (mw / 1000).toLocaleString(LOC(sprache), { minimumFractionDigits: 1, maximumFractionDigits: 1 });
54	
55	export const fmtUhr = (t) =>
56	  new Intl.DateTimeFormat("de-DE", { hour: "2-digit", minute: "2-digit", timeZone: "Europe/Berlin" }).format(new Date(t));
