15	/** Aktive Länderwahl speichern – nur aus einem Klick heraus aufrufen. */
16	export function landWaehlen(code) {
17	  const zeile = landCookieZeile(code, { https: typeof location !== "undefined" && location.protocol === "https:" });
18	  if (zeile) document.cookie = zeile;
19	}
