21	/**
22	 * Startwerte eines Rechners für das Land der Seite: AT/CH wählen die Region bzw. das Land vor
23	 * (die Länder-Engine sperrt dann ungeprüfte Werte, src/lib/invest/laender/sperre.js).
24	 * Gemeinsame Seite und DE: Startwerte unverändert (wie vor Welle 2).
25	 * @param {object} standard z. B. { regionId: "de-sued", … } oder { land: "DE" | "de", … }
26	 * @param {string|null} land
27	 */
28	export function landStart(standard, land) {
29	  if (!standard || !land || land === "DE") return standard;
30	  const s = { ...standard };
31	  if (typeof s.regionId === "string") s.regionId = land.toLowerCase();
32	  if (typeof s.land === "string") s.land = s.land === s.land.toLowerCase() ? land.toLowerCase() : land;
33	  return s;
34	}
