36	export default function useLand() {
37	  const pfad = usePathname() || "/";
38	  const land = useSeitenLand();
39	  const [gewaehlt, setGewaehlt] = useState(null);
40	  useEffect(() => {
41	    setGewaehlt(landAusCookie(document.cookie));
42	  }, [pfad]);
43	  const waehlen = useCallback((code) => {
44	    landWaehlen(code);
45	    setGewaehlt(code);
