3	import { useEffect, useRef, useState } from "react";
4	import { ladeEnergie } from "@/components/ui/useEnergyLive";
5	
6	// Alle Dashboard-Bausteine einer Seite teilen sich einen Abruf der vollen
7	// Zeitreihen (`/api/energie/live?voll=1`) statt ihn je Baustein zu wiederholen.
8	let zwischenspeicher = null;
9	let laufend = null;
10	
11	function ladeVoll() {
12	  if (zwischenspeicher && Date.now() - zwischenspeicher.zeit < 60000) return Promise.resolve(zwischenspeicher.daten);
13	  if (laufend) return laufend;
14	  laufend = ladeEnergie(true)
15	    .then((d) => {
16	      if (d) zwischenspeicher = { zeit: Date.now(), daten: d };
17	      return d;
18	    })
19	    .finally(() => {
20	      laufend = null;
21	    });
22	  return laufend;
23	}
24	
25	/**
26	 * Live-Daten mit Server-Startwert.
27	 * - Erstes Rendern = Server-HTML (SEO, keine Hydration-Abweichung).
28	 * - Danach alle 5 Minuten aktualisiert; „jetzt" läuft minütlich weiter.
29	 * - Liefert ein Abruf leere Reihen (Quelle kurz gestört), bleiben die
30	 *   bisherigen Werte stehen – Diagramme werden nie leer.
31	 */
32	export default function useLiveDaten(initial, { intervall = 5 * 60000 } = {}) {
33	  const [live, setLive] = useState(null);
34	  const [jetzt, setJetzt] = useState(null);
35	
36	  useEffect(() => {
37	    let aktiv = true;
38	    const holen = () => ladeVoll().then((d) => aktiv && d && setLive(d));
39	    holen();
40	    setJetzt(Date.now());
41	    const t1 = setInterval(holen, intervall);
42	    const t2 = setInterval(() => setJetzt(Date.now()), 60000);
43	    return () => {
44	      aktiv = false;
45	      clearInterval(t1);
46	      clearInterval(t2);
47	    };
48	  }, [intervall]);
49	
50	  const preisOk = live?.preis?.punkte?.length > 0;
51	  const erzeugungOk = live?.erzeugung?.zeitpunkt != null;
52	  const daten = {
53	    stand: (preisOk || erzeugungOk ? live.stand : initial?.stand) || null,
54	    preis: preisOk ? live.preis : initial?.preis || null,
55	    erzeugung: erzeugungOk ? live.erzeugung : initial?.erzeugung || null,
56	  };
57	  const standMs = daten.stand ? Date.parse(daten.stand) : 0;
58	  return { daten, jetzt: jetzt ?? standMs, live: preisOk || erzeugungOk };
59	}
