61	/** Breite eines Elements in px (für pixelgenaue SVG-Diagramme ohne Verzerrung) */
62	export function useBreite(standard = 960) {
63	  const ref = useRef(null);
64	  const [breite, setBreite] = useState(standard);
65	  useEffect(() => {
66	    const el = ref.current;
67	    if (!el || typeof ResizeObserver === "undefined") return;
68	    const ro = new ResizeObserver(([e]) => {
69	      const w = Math.round(e.contentRect.width);
70	      if (w > 0) setBreite(w);
71	    });
72	    ro.observe(el);
73	    return () => ro.disconnect();
74	  }, []);
75	  return [ref, breite];
76	}
