43	 *  - nurDE: gemeinsam a + „(gilt für Deutschland)“, DE unverändert, AT/CH nurDeText()
44	 *  - sonst unverändert (gilt in DACH)
45	 * Antworten als JSX bekommen aText für das FAQ-Schema (ui/Faq).
46	 * markieren: true → auch in AT/CH die deutsche Antwort mit „(gilt für Deutschland)“ statt des Hinweises
47	 *   (nur für ausdrücklich deutsche Marktdaten, z. B. EEG-Ausschreibungsergebnisse auf /marktdaten).
48	 */
49	export function faqFuerLand(items, land, { markieren = false, sprache = "de" } = {}) {
50	  const l = landCode(land);
51	  return items.map((it) => {
52	    const basis = ohneSteuerung(it);
53	    if (l && it[l]) return { ...basis, ...it[l] };
54	    if (!it.nurDE) return basis;
55	    if (l === "DE") return basis;
56	    if (!l || markieren) {
57	      const text = typeof it.a === "string" ? it.a : it.aText;
58	      return {
59	        ...basis,
60	        a: (
61	          <>
62	            {it.a} <GiltFuer />
63	          </>
64	        ),
65	        ...(text ? { aText: text } : {}),
66	      };
67	    }
68	    return { q: it.q, a: nurDeText(l, it.nurDE === true ? undefined : it.nurDE, sprache) };
69	  });
70	}
71	
72	/**
73	 * Beliebige Liste je Land (Faktenkarten, Regelkarten, Stichpunkte).
74	 * Eintrag mit nurDE: "Thema" gilt nur für Deutschland; AT/CH-Eintrag ersetzt ihn im Land.
75	 * @param {object[]} items
76	 * @param {string|null} land
77	 * @param {(it: object, l: string) => object|null} ersatz Ersatz in AT/CH ohne Ländereintrag (null = weglassen)
78	 * @param {(it: object) => object} [vermerk] Fassung für die gemeinsame Seite (Standard: unverändert)
79	 */
80	export function listeFuerLand(items, land, ersatz, vermerk = (it) => it) {
81	  const l = landCode(land);
82	  return items
83	    .map((it) => {
84	      const basis = ohneSteuerung(it);
85	      if (l && it[l]) return { ...basis, ...it[l] };
86	      if (!it.nurDE || l === "DE") return basis;
87	      if (!l) return vermerk(basis);
88	      return ersatz ? ersatz(basis, l, it.nurDE) : null;
89	    })
90	    .filter(Boolean);
91	}
92	
93	/** Inline: Satz nur mit deutschen Werten (in einem Absatz). */
94	export function NurDE({ land, thema, themaEn, children, vermerk = true, dunkel = false }) {
95	  const l = landCode(land);
96	  if (l === "DE") return children;
97	  if (!l)
98	    return (
99	      <>
100	        {children}
101	        {vermerk && (
102	          <>
103	            {" "}
104	            <GiltFuer dunkel={dunkel} />
105	          </>
106	        )}
107	      </>
108	    );
109	  return (
110	    <span data-land-hinweis={l}>
111	      <T de={`${landHinweisText(l, thema)}.`} en={`${landHinweisTextEn(l, themaEn)}.`} />
112	    </span>
113	  );
114	}
115	
116	/** Ganzer Absatz nur mit deutschen Werten. AT/CH: kompakte LandHinweis-Zeile. */
117	export function NurDEAbsatz({ land, thema, themaEn, children, className, dunkel = false }) {
118	  const l = landCode(land);
119	  if (l && l !== "DE") return <LandHinweis land={l} thema={thema} themaEn={themaEn} zeile className={className} />;
120	  return (
121	    <p className={className}>
122	      {children}
123	      {!l && (
124	        <>
125	          {" "}
126	          <GiltFuer dunkel={dunkel} />
127	        </>
128	      )}
129	    </p>
130	  );
131	}
132	
133	/* ------------------------------------------------------------------ */
134	/* Geprüfte Länderfakten (Faktenregister, status „geprueft“)           */
135	/* ------------------------------------------------------------------ */
136	
137	/**
138	 * Rechenwert Jahresertrag Freiflächen-PV für AT/CH aus dem Faktenregister (PVGIS, am Original geprüft).
139	 * @returns {{ wert: string, zahl: number, text: string, quelle: object } | null}
140	 */
141	export function ertragFuerLand(land, sprache = "de") {
142	  const l = landCode(land);
143	  if (l !== "AT" && l !== "CH") return null;
144	  const f = fakt(`region.${l.toLowerCase()}.ertrag`, l);
145	  if (!f || f.status !== "geprueft") return null;
146	  if (sprache === "en") {
147	    const gebietEn = l === "AT" ? "in Austria's lowlands and hill country" : "on the Swiss Plateau";
148	    return { wert: fmtZahl(f.wert, l), zahl: f.wert, text: `kWh per kWp and year – calculation value for ground-mounted PV ${gebietEn} (PVGIS)`, quelle: f.quelle };
149	  }
150	  const gebiet = l === "AT" ? "im österreichischen Flach- und Hügelland" : "im Schweizer Mittelland";
151	  return { wert: fmtZahl(f.wert, l), zahl: f.wert, text: `kWh je kWp und Jahr – Rechenwert für Freiflächen-PV ${gebiet} (PVGIS)`, quelle: f.quelle };
152	}
153	
154	/**
155	 * Förderweg für Photovoltaik in AT/CH – belegt durch die geprüften Termine im Faktenregister
156	 * (EAG-Fördercall der EAG-Abwicklungsstelle bzw. Pronovo-Auktionen), ohne Fördersätze.
157	 */
158	export function foerderwegFuerLand(land, sprache = "de") {
159	  const l = landCode(land);
160	  const en = sprache === "en";
161	  if (l === "AT") {
162	    const f = fakt("termin.eag.investitionszuschussCall3", "AT", { stichtag: "2026-10-04" });
163	    if (f?.status !== "geprueft") return null;
164	    return {
165	      wert: "EAG",
166	      text: en
167	        ? "In Austria, investment grants for photovoltaics are awarded by the EAG funding settlement agency (EAG-Abwicklungsstelle) through funding calls"
168	        : "Investitionszuschüsse für Photovoltaik vergibt in Österreich die EAG-Abwicklungsstelle über Fördercalls",
169	      quelle: f.quelle,
170	    };
171	  }
172	  if (l === "CH") {
173	    const f = fakt("termin.pronovo.auktionRunde4", "CH", { stichtag: "2026-10-04" });
174	    if (f?.status !== "geprueft") return null;
175	    return {
176	      wert: "Pronovo",
177	      text: en
178	        ? "awards the high one-off remuneration and the sliding market premium for PV in Switzerland through auctions"
179	        : "vergibt in der Schweiz die hohe Einmalvergütung und die gleitende Marktprämie für PV über Auktionen",
180	      quelle: f.quelle,
181	    };
182	  }
183	  return null;
184	}
185	
186	/**
187	 * Block mit Werten/Regeln für Deutschland (z. B. Methodik eines Rechners).
188	 * DE und gemeinsam: unverändert (auf Rechnerseiten trägt die Annahmen-Box daneben „gilt für Deutschland“),
189	 * AT/CH: eine LandHinweis-Zeile statt des Blocks.
190	 */
191	export function NurDEBlock({ land, thema = "Annahmen und Rechenwerte", themaEn = "Assumptions and figures", children, className }) {
192	  const l = landCode(land);
193	  if (l && l !== "DE") return <LandHinweis land={l} thema={thema} themaEn={themaEn} zeile className={className} />;
194	  return children;
195	}
