1	"use client";
2	
3	import { useMemo } from "react";
4	import { ArrowDown, ArrowDownRight, ArrowUpRight, Leaf, Sun, Wind, Gauge, RefreshCw } from "lucide-react";
5	import { LiveDot } from "@/components/ui/LiveTicker";
6	import useLiveDaten from "./useLiveDaten";
7	import { preisTage, zeitfenster, formate } from "./berechnung";
8	import { useSprache } from "@/components/Sprache/SpracheKontext";
9	
10	/* Sprachmodell: feste Texte je Sprache */
11	const TEXTE = {
12	  de: { guenstig: "eher günstig", teuer: "eher teuer", mittel: "mittleres Niveau", stand: "Stand", alle5: "aktualisiert alle 5 Min.", jetzt: "Börsenstrompreis jetzt", dayAhead: "Day-Ahead, netto", fuerHeute: "für heute", nichtAbrufbar: "Der aktuelle Börsenpreis ist gerade nicht abrufbar. Die Anzeige aktualisiert sich automatisch.", tief: "Tagestief", hoch: "Tageshoch", um: (u) => `um ${u} Uhr`, avg: "Ø heute", negativ: (h) => `${h} h negativ`, jeKwh: "je kWh netto", ee: "Erneuerbare", ueber: "über 100 %: Überschuss", anteil: "Anteil am Verbrauch", nachts: "nachts keine Erzeugung", desVerbrauchs: (p) => `${p} % des Verbrauchs`, einspeisung: "Einspeisung jetzt", windSub: "an Land und auf See", verbrauch: "Verbrauch", netzlast: "Netzlast Deutschland", erzeugungStand: "Erzeugung: Stand", zumVerlauf: "Zum Tagesverlauf", null: "0 Uhr", vierundzwanzig: "24 Uhr", guenstigste: "Günstigste 3 h:", aktuellerPreis: "Aktueller Preis" },
13	  en: { guenstig: "relatively cheap", teuer: "relatively expensive", mittel: "mid-range", stand: "As of", alle5: "updated every 5 min", jetzt: "Exchange power price now", dayAhead: "day-ahead, net", fuerHeute: "for today", nichtAbrufbar: "The current exchange price cannot be retrieved right now. The display updates automatically.", tief: "Daily low", hoch: "Daily high", um: (u) => `at ${u}`, avg: "Ø today", negativ: (h) => `${h} h negative`, jeKwh: "per kWh, net", ee: "Renewables", ueber: "above 100 %: surplus", anteil: "share of consumption", nachts: "no generation at night", desVerbrauchs: (p) => `${p} % of consumption`, einspeisung: "feed-in now", windSub: "onshore and offshore", verbrauch: "Consumption", netzlast: "Grid load in Germany", erzeugungStand: "Generation: as of", zumVerlauf: "To the daily profile", null: "00:00", vierundzwanzig: "24:00", guenstigste: "Cheapest 3 h:", aktuellerPreis: "Current price" },
14	};
15	
16	/**
17	 * Live-Kennzahlen im dunklen Seitenkopf: Börsenpreis jetzt (Hero-Zahl) mit
18	 * Tagesverlauf-Sparkline, Tagestief/-hoch, Erneuerbare, Solar, Wind, Last.
19	 */
20	export default function LiveKennzahlen({ initial }) {
21	  const { daten, jetzt } = useLiveDaten(initial);
22	  const sprache = useSprache();
23	  const { ct, gw, uhr, spanne, zahl } = formate(sprache);
24	  const w = TEXTE[sprache === "en" ? "en" : "de"];
25	  const tage = useMemo(() => preisTage(daten.preis, jetzt), [daten.preis, jetzt]);
26	  const e = daten.erzeugung || {};
27	  const heute = tage.heute;
28	  const aktuell = tage.aktuell;
29	  const fenster = useMemo(() => (heute ? zeitfenster(heute.punkte, 180, tage.schrittMs).guenstig : null), [heute, tage.schrittMs]);
30	
31	  const nachts = e.solarMw != null && e.solarMw < 100;
32	  const eeAnteil = e.eeAnteil != null ? Math.round(e.eeAnteil) : null;
33	
34	  // Position des aktuellen Preises innerhalb der Tagesspanne (0–1)
35	  const lage = heute && aktuell && heute.max.eurMwh > heute.min.eurMwh
36	    ? (aktuell.eurMwh - heute.min.eurMwh) / (heute.max.eurMwh - heute.min.eurMwh)
37	    : null;
38	  const einordnung = lage == null ? null : lage < 0.33 ? w.guenstig : lage > 0.66 ? w.teuer : w.mittel;
39	
40	  return (
41	    <div className="ov-hero-in mt-12 grid gap-4 lg:grid-cols-[1.25fr_1fr]" style={{ "--ov-delay": "300ms" }}>
42	      {/* Börsenpreis jetzt */}
43	      <div className="ov-glass relative overflow-hidden rounded-3xl p-6 sm:p-8">
44	        <div className="flex flex-wrap items-center justify-between gap-3 text-[13px]">
45	          <p className="flex items-center gap-2 font-semibold uppercase tracking-[0.14em] text-ov-300">
46	            <LiveDot />
47	            Live
48	            <span className="font-normal normal-case tracking-normal text-white/60">
49	              · {w.stand} {daten.stand ? uhr(Date.parse(daten.stand)) : "–"}{sprache === "en" ? "" : " Uhr"}
50	            </span>
51	          </p>
52	          <p className="flex items-center gap-1.5 text-white/50">
53	            <RefreshCw aria-hidden="true" className="h-3.5 w-3.5" />
54	            {w.alle5}
55	          </p>
56	        </div>
57	
58	        <p className="mt-6 text-[15px] text-white/70">{w.jetzt}</p>
59	        {aktuell ? (
60	          <>
61	            <p className="mt-1 flex flex-wrap items-baseline gap-x-3 font-display font-extrabold leading-none tracking-tight text-white">
62	              <span className="text-[clamp(3.25rem,2.4rem+3.6vw,5.25rem)]">{ct(aktuell.eurMwh)}</span>
63	              <span className="text-[clamp(1.1rem,0.9rem+0.8vw,1.5rem)] font-bold text-white/70">ct/kWh</span>
64	            </p>
65	            <p className="mt-3 text-[14px] text-white/60">
66	              {spanne(aktuell.t, aktuell.t + tage.schrittMs)} · {w.dayAhead}
67	              {einordnung && (
68	                <>
69	                  {" · "}
70	                  <span className={lage < 0.33 ? "font-semibold text-ov-300" : lage > 0.66 ? "font-semibold text-sun-300" : "text-white/80"}>{einordnung}</span> {w.fuerHeute}
71	                </>
72	              )}
73	            </p>
74	          </>
75	        ) : (
76	          <p className="mt-2 max-w-md text-[16px] leading-relaxed text-white/75">
77	            {w.nichtAbrufbar}
78	          </p>
79	        )}
80	
81	        {heute && <Sparkline tag={heute} jetzt={jetzt} schrittMs={tage.schrittMs} fenster={fenster} aktuell={aktuell} w={w} ct={ct} spanne={spanne} />}
82	
83	        {heute && (
84	          <dl className="mt-5 grid grid-cols-3 gap-3 border-t border-white/10 pt-5">
85	            <div>
86	              <dt className="flex items-center gap-1.5 text-[12.5px] text-white/55">
87	                <ArrowDownRight aria-hidden="true" className="h-3.5 w-3.5 text-ov-300" />
88	                {w.tief}
89	              </dt>
90	              <dd className="mt-1 font-display text-[20px] font-extrabold text-white sm:text-[24px]">{ct(heute.min.eurMwh)} ct</dd>
91	              <dd className="text-[12.5px] text-white/55">{w.um(uhr(heute.min.t))}</dd>
92	            </div>
93	            <div>
94	              <dt className="flex items-center gap-1.5 text-[12.5px] text-white/55">
95	                <ArrowUpRight aria-hidden="true" className="h-3.5 w-3.5 text-sun-300" />
96	                {w.hoch}
97	              </dt>
98	              <dd className="mt-1 font-display text-[20px] font-extrabold text-white sm:text-[24px]">{ct(heute.max.eurMwh)} ct</dd>
99	              <dd className="text-[12.5px] text-white/55">{w.um(uhr(heute.max.t))}</dd>
100	            </div>
101	            <div>
102	              <dt className="text-[12.5px] text-white/55">{w.avg}</dt>
103	              <dd className="mt-1 font-display text-[20px] font-extrabold text-white sm:text-[24px]">{ct(heute.avg)} ct</dd>
104	              <dd className="text-[12.5px] text-white/55">{heute.negativStunden > 0 ? w.negativ(zahl(heute.negativStunden, heute.negativStunden % 1 ? 2 : 0)) : w.jeKwh}</dd>
105	            </div>
106	          </dl>
107	        )}
108	      </div>
109	
110	      {/* Erzeugung */}
111	      <div className="grid grid-cols-2 gap-4">
112	        <Kachel
113	          icon={Leaf}
114	          farbe="text-ov-300"
115	          label={w.ee}
116	          wert={eeAnteil != null ? `${eeAnteil} %` : "–"}
117	          sub={eeAnteil != null && eeAnteil > 100 ? w.ueber : w.anteil}
118	        >
119	          {eeAnteil != null && (
120	            <div className="mt-4 h-1.5 overflow-hidden rounded-full bg-white/10" aria-hidden="true">
121	              <div className="h-full rounded-full bg-ov-400 transition-[width] duration-700" style={{ width: `${Math.min(eeAnteil, 100)}%` }} />
122	            </div>
123	          )}
124	        </Kachel>
125	        <Kachel
126	          icon={Sun}
127	          farbe="text-sun-300"
128	          label="Solar"
129	          wert={e.solarMw != null ? `${gw(e.solarMw)} GW` : "–"}
130	          sub={nachts ? w.nachts : e.solarAnteil != null ? w.desVerbrauchs(Math.round(e.solarAnteil)) : w.einspeisung}
131	        />
132	        <Kachel icon={Wind} farbe="text-navy-200" label="Wind" wert={e.windMw != null ? `${gw(e.windMw)} GW` : "–"} sub={w.windSub} />
133	        <Kachel icon={Gauge} farbe="text-white/80" label={w.verbrauch} wert={e.lastMw != null ? `${gw(e.lastMw)} GW` : "–"} sub={w.netzlast} />
134	        <p className="col-span-2 flex flex-wrap items-center justify-between gap-2 px-1 text-[12.5px] text-white/50">
135	          <span>{w.erzeugungStand} {e.zeitpunkt ? `${uhr(e.zeitpunkt)}${sprache === "en" ? "" : " Uhr"}` : "–"}</span>
136	          <a href="#preisverlauf" className="inline-flex min-h-11 items-center gap-1.5 font-semibold text-white/80 hover:text-white">
137	            {w.zumVerlauf}
138	            <ArrowDown aria-hidden="true" className="h-3.5 w-3.5" />
139	          </a>
140	        </p>
141	      </div>
142	    </div>
143	  );
144	}
145	
146	function Kachel({ icon: Icon, farbe, label, wert, sub, children }) {
147	  return (
148	    <div className="ov-glass flex flex-col rounded-3xl p-5 sm:p-6">
149	      <p className="flex items-center gap-2 text-[13.5px] text-white/65">
150	        <Icon aria-hidden="true" className={`h-4 w-4 ${farbe}`} />
151	        {label}
152	      </p>
153	      <p className="mt-auto pt-6 font-display text-[clamp(1.6rem,1.2rem+1.4vw,2.4rem)] font-extrabold leading-none tracking-tight text-white">{wert}</p>
154	      <p className="mt-2 text-[12.5px] leading-snug text-white/55">{sub}</p>
155	      {children}
156	    </div>
157	  );
158	}
159	
160	/** Tagesverlauf im Kleinformat (Deko, Werte stehen daneben und im Diagramm) */
161	function Sparkline({ tag, jetzt, schrittMs, fenster, aktuell, w, ct, spanne }) {
162	  const W = 600;
163	  const H = 84;
164	  const werte = tag.punkte.map((p) => p.eurMwh);
165	  const lo = Math.min(0, ...werte);
166	  const hi = Math.max(...werte, lo + 1);
167	  const x = (t) => ((t - tag.start) / (tag.ende - tag.start)) * W;
168	  const y = (v) => 6 + (1 - (v - lo) / (hi - lo)) * (H - 12);
169	  let d = "";
170	  tag.punkte.forEach((p, i) => {
171	    d += `${i ? "L" : "M"}${x(p.t + schrittMs / 2).toFixed(1)},${y(p.eurMwh).toFixed(1)}`;
172	  });
