64	    const heute = tage.heute;
65	    if (!heute) return null;
66	    const schritt = tage.schrittMs;
67	    const solarAn = new Map();
68	    solar.zeiten.forEach((t, i) => {
69	      const v = Number(solar.werte[i]);
70	      if (Number.isFinite(v)) solarAn.set(Math.floor(t / schritt) * schritt, Math.max(0, v));
71	    });
