78	      if (p.eurMwh < 0) negativ++;
79	      const s = solarAn.get(p.t);
80	      if (s == null) continue;
81	      sumSP += s * p.eurMwh;
82	      sumS += s;
83	      if (p.eurMwh < 0) sumSNeg += s;
84	      letzte = p.t;
85	    }
