88	    return {
89	      genug,
90	      capture: sumS > 0 ? sumSP / sumS : null,
91	      base: heute.avg,
92	      rate: sumS > 0 && heute.avg > 0 ? sumSP / sumS / heute.avg : null,
93	      negativ,
94	      negativStunden: (negativ * schritt) / 3600000,
95	      solarNegAnteil: sumS > 0 ? sumSNeg / sumS : 0,
