1	// Reine Rechen- und Formatierhilfen für das Strommarkt-Dashboard.
2	// Ohne "use client": wird von Server- und Client-Komponenten genutzt.
3	
4	export const TZ = "Europe/Berlin";
5	export const STUNDE = 3600000;
6	
7	const datumFmt = new Intl.DateTimeFormat("sv-SE", { timeZone: TZ });
8	const uhrFmt = new Intl.DateTimeFormat("de-DE", { hour: "2-digit", minute: "2-digit", timeZone: TZ });
9	const tagFmt = new Intl.DateTimeFormat("de-DE", { weekday: "long", day: "numeric", month: "long", timeZone: TZ });
10	const kurzTagFmt = new Intl.DateTimeFormat("de-DE", { weekday: "short", day: "2-digit", month: "2-digit", timeZone: TZ });
11	
12	/** YYYY-MM-DD in deutscher Zeit */
13	export const berlinTag = (t) => datumFmt.format(new Date(t));
14	/** hh:mm in deutscher Zeit */
15	export const uhr = (t) => uhrFmt.format(new Date(t));
16	/** „Sonntag, 13. September" */
17	export const tagLang = (t) => tagFmt.format(new Date(t));
18	/** „So., 13.09." */
19	export const tagKurz = (t) => kurzTagFmt.format(new Date(t));
20	
21	/** Zahl deutsch formatiert, echtes Minuszeichen */
22	export const zahl = (n, stellen = 1) =>
23	  n == null || Number.isNaN(n)
24	    ? "–"
25	    : n.toLocaleString("de-DE", { minimumFractionDigits: stellen, maximumFractionDigits: stellen }).replace("-", "−");
26	
27	/** €/MWh -> „12,3" (ct/kWh) */
28	export const ct = (eurMwh, stellen = 1) => (eurMwh == null ? "–" : zahl(eurMwh / 10, stellen));
29	/** MW -> „12,3" (GW) */
30	export const gw = (mw, stellen = 1) => (mw == null ? "–" : zahl(mw / 1000, stellen));
31	
32	/** Uhrzeit-Spanne „13:00–16:00 Uhr" */
33	export const spanne = (von, bis) => `${uhr(von)}–${uhr(bis)} Uhr`;
34	
35	/** Kennzahlen eines Tages */
36	function tagesStat(punkte, schrittMs) {
37	  if (!punkte.length) return null;
38	  let min = punkte[0];
39	  let max = punkte[0];
40	  let summe = 0;
41	  let negativ = 0;
42	  for (const p of punkte) {
43	    if (p.eurMwh < min.eurMwh) min = p;
44	    if (p.eurMwh > max.eurMwh) max = p;
45	    if (p.eurMwh < 0) negativ++;
46	    summe += p.eurMwh;
47	  }
48	  return {
49	    punkte,
50	    datum: berlinTag(punkte[0].t),
51	    start: punkte[0].t,
52	    ende: punkte[punkte.length - 1].t + schrittMs,
53	    avg: summe / punkte.length,
54	    min,
55	    max,
56	    negativStunden: (negativ * schrittMs) / STUNDE,
57	    vollstaendig: punkte.length * schrittMs >= 23 * STUNDE,
58	  };
59	}
60	
61	/**
62	 * Preise nach Tagen gruppieren.
63	 * Rückgabe: { schrittMs, aufloesungMin, aktuell, heute, morgen, zukunft }
64	 */
65	export function preisTage(preis, jetzt) {
66	  const punkte = (preis?.punkte || []).filter((p) => typeof p.eurMwh === "number").sort((a, b) => a.t - b.t);
67	  const aufloesungMin = preis?.aufloesungMin || 60;
68	  const schrittMs = aufloesungMin * 60000;
69	  const heuteStr = berlinTag(jetzt);
70	
71	  const gruppen = new Map();
72	  for (const p of punkte) {
73	    const k = berlinTag(p.t);
74	    if (!gruppen.has(k)) gruppen.set(k, []);
75	    gruppen.get(k).push(p);
76	  }
77	  const heute = gruppen.has(heuteStr) ? tagesStat(gruppen.get(heuteStr), schrittMs) : null;
78	  const spaeterKey = [...gruppen.keys()].filter((k) => k > heuteStr).sort()[0];
79	  const morgen = spaeterKey ? tagesStat(gruppen.get(spaeterKey), schrittMs) : null;
80	  const aktuell = punkte.find((p) => p.t <= jetzt && jetzt < p.t + schrittMs) || null;
81	  // Ab der laufenden Viertelstunde bis zum Ende der veröffentlichten Preise
82	  const zukunft = punkte.filter((p) => p.t + schrittMs > jetzt);
83	
84	  return { schrittMs, aufloesungMin, aktuell, heute, morgen, zukunft, quelle: preis?.quelle || null };
85	}
86	
87	/**
88	 * Günstigstes und teuerstes zusammenhängendes Zeitfenster.
89	 * dauerMin: Fensterlänge; Rückgabe { guenstig, teuer } mit { start, ende, avg } oder null.
90	 */
91	export function zeitfenster(punkte, dauerMin, schrittMs) {
92	  const n = Math.max(1, Math.round((dauerMin * 60000) / schrittMs));
93	  if (!punkte || punkte.length < n) return { guenstig: null, teuer: null };
94	  let guenstig = null;
95	  let teuer = null;
96	  let summe = 0;
97	  for (let i = 0; i < punkte.length; i++) {
98	    summe += punkte[i].eurMwh;
99	    if (i >= n) summe -= punkte[i - n].eurMwh;
100	    if (i < n - 1) continue;
101	    const a = i - n + 1;
102	    // Nur lückenlose Fenster zählen
103	    if (punkte[i].t - punkte[a].t !== (n - 1) * schrittMs) continue;
104	    const avg = summe / n;
105	    const f = { start: punkte[a].t, ende: punkte[i].t + schrittMs, avg };
106	    if (!guenstig || avg < guenstig.avg) guenstig = f;
107	    if (!teuer || avg > teuer.avg) teuer = f;
108	  }
109	  return { guenstig, teuer };
110	}
111	
112	/** Stundenmittel für Tabellen und Mini-Balken */
113	export function stundenmittel(punkte) {
114	  const map = new Map();
115	  for (const p of punkte) {
116	    const s = Math.floor(p.t / STUNDE) * STUNDE;
117	    if (!map.has(s)) map.set(s, []);
118	    map.get(s).push(p.eurMwh);
119	  }
120	  return [...map.entries()].map(([t, w]) => ({
121	    t,
122	    avg: w.reduce((a, b) => a + b, 0) / w.length,
123	    min: Math.min(...w),
124	    max: Math.max(...w),
125	  }));
126	}
127	
128	/** „schöne" Achsenschritte */
129	export function achse(lo, hi, ziel = 5) {
130	  if (!(hi > lo)) hi = lo + 1;
131	  const roh = (hi - lo) / ziel;
132	  const mag = 10 ** Math.floor(Math.log10(roh));
133	  const schritt = [1, 2, 2.5, 5, 10].map((f) => f * mag).find((s) => s >= roh) || 10 * mag;
134	  const von = Math.floor(lo / schritt) * schritt;
135	  const bis = Math.ceil(hi / schritt) * schritt;
136	  const ticks = [];
137	  for (let v = von; v <= bis + schritt / 2; v += schritt) ticks.push(Math.round(v * 1000) / 1000);
138	  return { von, bis, ticks, schritt };
139	}
