145	// Farbpalette mit dem Validator des dataviz-Skills geprüft (Hell, Fläche #ffffff):
146	// Stapelnachbarn CVD ΔE ≥ 17,3, Normalsicht ΔE ≥ 22,8. Einige helle Töne liegen
147	// unter 3:1 Kontrast – deshalb immer Legende, Tooltip und Tabellenansicht.
148	// Reihenfolge = Stapel von unten nach oben.
149	export const QUELLEN = [
150	  { key: "braunkohle", name: "Braunkohle", farbe: "#a0561c", ee: false },
151	  { key: "steinkohle", name: "Steinkohle", farbe: "#4a3aa7", ee: false },
152	  { key: "gas", name: "Erdgas", farbe: "#f29a4a", ee: false },
153	  { key: "sonstige", name: "Sonstige", farbe: "#c4cad5", ee: false, text: "#151a24" },
154	  { key: "biomasse", name: "Biomasse", farbe: "#2d7a1f", ee: true },
155	  { key: "wasser", name: "Wasserkraft", farbe: "#1aa7c4", ee: true },
156	  { key: "windOffshore", name: "Wind auf See", farbe: "#1e4fa3", ee: true },
157	  { key: "windOnshore", name: "Wind an Land", farbe: "#5aa3ec", ee: true },
158	  { key: "solar", name: "Solar", farbe: "#eda100", ee: true },
159	];
