161	/** Hell genug für dunklen Text? (relative Luminanz) */
162	export function textAuf(hex) {
163	  const n = parseInt(hex.slice(1), 16);
164	  const kanal = (c) => {
165	    const s = c / 255;
166	    return s <= 0.03928 ? s / 12.92 : ((s + 0.055) / 1.055) ** 2.4;
167	  };
168	  const l = 0.2126 * kanal((n >> 16) & 255) + 0.7152 * kanal((n >> 8) & 255) + 0.0722 * kanal(n & 255);
169	  return l > 0.3 ? "#151a24" : "#ffffff";
170	}
