172	/**
173	 * Letzte `stunden` Stunden der Erzeugung als Zeilen.
174	 * Rückgabe null, wenn keine verwertbaren Daten vorliegen.
175	 */
176	export function erzeugungsVerlauf(erzeugung, stunden = 24) {
177	  const zeiten = erzeugung?.zeiten || [];
178	  const s = erzeugung?.serien || {};
179	  let ende = -1;
180	  for (let i = zeiten.length - 1; i >= 0; i--) {
181	    if (s.last?.[i] != null && s.solar?.[i] != null) {
182	      ende = i;
183	      break;
184	    }
185	  }
186	  if (ende < 0) return null;
187	  const grenze = zeiten[ende] - stunden * STUNDE;
188	  const zeilen = [];
189	  for (let i = 0; i <= ende; i++) {
190	    if (zeiten[i] < grenze) continue;
191	    const z = { t: zeiten[i], last: s.last?.[i] ?? null, eeAnteil: s.eeAnteil?.[i] ?? null };
192	    let summe = 0;
193	    for (const q of QUELLEN) {
194	      const v = Math.max(0, Number(s[q.key]?.[i]) || 0);
195	      z[q.key] = v;
196	      summe += v;
197	    }
198	    z.summe = summe;
199	    if (summe > 0) zeilen.push(z);
200	  }
201	  return zeilen.length >= 2 ? zeilen : null;
202	}
