229	/**
230	 * Formatierhilfen je Sprache. `uhrText(t)` hängt im Deutschen „Uhr“ an, im Englischen nicht;
231	 * `U` ist das Suffix für Stundenangaben in festen Texten („0 Uhr“ / „00:00“ siehe Aufrufer).
232	 */
233	export function formate(sprache = "de") {
234	  if (sprache !== "en") {
235	    return { en: false, zahl, ct, gw, uhr, tagLang, tagKurz, spanne, uhrText: (t) => `${uhr(t)} Uhr`, U: " Uhr", quelle: (q) => q.name };
236	  }
