246	    spanne: (von, bis) => `${uhrEn(von)}–${uhrEn(bis)}`,
247	    uhrText: uhrEn,
248	    U: "",
249	    quelle: (q) => QUELLEN_EN[q.key] ?? q.name,
250	  };
